function completeGeometry(id: string, geometry: GeometryDraft): SuwonImageGeometry {
  return {
    ...geometry,
    labelFontSize: geometry.labelFontSize ?? 54,
    shortLabel: geometry.shortLabel ?? id.replace('suwon-', '').toUpperCase(),
  };
}

